package com.bananalab.lite;
import android.content.*;import org.json.*;import java.io.*;import java.nio.charset.*;import java.security.*;import java.text.Normalizer;import java.util.*;
/** Immutable UTF-8 documents plus a transactional, replaceable chunk index. */
final class NotebookDisk{
 static final int DOCUMENT_CHARS=16000000,MAX_DOCUMENTS=1024,CHUNK=2048;static final long DOCUMENT_BYTES=67108864L,TOTAL_BYTES=536870912L;
 interface Provider{NotebookDisk notebook()throws Exception;}
 interface Index{
  void begin()throws Exception;void end(boolean commit)throws Exception;String meta(String key)throws Exception;void meta(String key,String value)throws Exception;
  List<Doc> list(int limit)throws Exception;Doc get(String id)throws Exception;long bytes()throws Exception;int count()throws Exception;long chunks()throws Exception;
  void remove(String id)throws Exception;void doc(Doc doc)throws Exception;void chunk(String id,int ordinal,String text,String tokens,boolean definition)throws Exception;
  List<Hit> search(Set<String> terms,int limit)throws Exception;List<Hit> sample(int limit)throws Exception;List<Hit> slice(String id,int ordinal,int limit)throws Exception;List<Hit> first(String id,int limit)throws Exception;void clear()throws Exception;
 }
 static final class Doc{
  String id,title,source,origin,file,sha;long saved,bytes;int chars;boolean truncated;
  JSONObject json()throws Exception{return new JSONObject().put("id",id).put("title",title).put("source",source).put("origin",origin).put("saved",saved).put("bytes",bytes).put("chars",chars).put("sha256",sha).put("truncated",truncated);}
  static Doc read(JSONObject j)throws Exception{RuntimeProgram.keys(j,"id","title","source","origin","saved","bytes","chars","sha256","truncated");Doc d=new Doc();d.id=j.getString("id");d.title=j.getString("title");d.source=j.getString("source");d.origin=j.getString("origin");d.saved=j.getLong("saved");d.bytes=j.getLong("bytes");d.chars=j.getInt("chars");d.sha=j.getString("sha256");d.truncated=j.getBoolean("truncated");d.validate();return d;}
  void validate()throws Exception{if(id==null||!id.matches("[a-f0-9]{64}")||sha==null||!sha.matches("[a-f0-9]{64}")||title==null||title.length()>160||source==null||source.length()>2000||origin==null||!origin.matches("user|web")||origin.equals("web")&&!source.startsWith("https://")||saved<0||chars<1||chars>DOCUMENT_CHARS||bytes<1||bytes>DOCUMENT_BYTES)throw new IOException("Metadatos de documento inválidos");}
  JSONObject row(String text)throws Exception{return new JSONObject().put("id",id).put("title",title).put("source",source).put("origin",origin).put("saved",saved).put("truncated",truncated).put("text",text);}
 }
 static final class Hit{Doc doc;String text;int ordinal;Hit(Doc d,String t){this(d,t,0);}Hit(Doc d,String t,int n){doc=d;text=t;ordinal=n;}}
 static final class Stage{Doc doc;File file;Stage(Doc d,File f){doc=d;file=f;}}
 final File root;final Index index;static NotebookDisk live;
 NotebookDisk(File root,Index index)throws Exception{this.root=root;this.index=index;if(!root.isDirectory()&&!root.mkdirs())throw new IOException("No pude preparar los documentos privados");}
 static synchronized NotebookDisk of(Context c)throws Exception{if(c instanceof Provider)return ((Provider)c).notebook();if(live==null){Context app=c.getApplicationContext();NotebookSQLite sql=new NotebookSQLite(app);try{NotebookDisk candidate=new NotebookDisk(app.getDir("knowledge-documents",0),sql);candidate.migrate(c);candidate.cleanup();live=candidate;}catch(Exception e){sql.close();throw e;}}return live;}
 synchronized void migrate(Context c)throws Exception{SharedPreferences p=KnowledgeNotebook.prefs(c);if(p.contains("entries")&&!"1".equals(index.meta("legacy_migrated"))){JSONArray old=new JSONArray(p.getString("entries","[]"));KnowledgeNotebook.validate(old);for(int i=0;i<old.length();i++){JSONObject r=old.getJSONObject(i);if(index.get(r.getString("id"))!=null)continue;Stage s=stage(r.getString("title"),new StringReader(r.getString("text")),r.getString("source"),r.getString("origin"),r.getLong("saved"));s.doc.id=r.getString("id");s.doc.truncated=r.getBoolean("truncated");install(Collections.singletonList(s),true,false);}
   index.begin();try{index.meta("initialized","1");index.meta("legacy_migrated","1");String last=p.getString("last","");if(index.get(last)!=null)index.meta("last",last);index.end(true);}catch(Exception e){rollback();throw e;}}
  if("1".equals(index.meta("legacy_migrated"))&&p.contains("entries")&&!p.edit().remove("entries").remove("last").commit())throw new IOException("Migré los documentos; conservé también la copia antigua porque no pude retirar sus preferencias");
 }
 synchronized void cleanup()throws Exception{Set<String> refs=new HashSet<>();for(Doc d:index.list(MAX_DOCUMENTS))refs.add(d.file);File[] files=root.listFiles();if(files!=null)for(File f:files)if((f.getName().endsWith(".txt")||f.getName().endsWith(".part"))&&!refs.contains(f.getName()))f.delete();}
 static Reader reader(InputStream in){return new InputStreamReader(in,Charset.forName("UTF-8").newDecoder().onMalformedInput(CodingErrorAction.REPORT).onUnmappableCharacter(CodingErrorAction.REPORT));}
 static String hex(byte[] b){StringBuilder s=new StringBuilder();for(byte x:b)s.append(String.format(java.util.Locale.ROOT,"%02x",x&255));return s.toString();}
 synchronized Stage stage(String title,Reader input,String source,String origin,long saved)throws Exception{
  if(title==null||source==null||source.length()>2000||!origin.matches("user|web")||origin.equals("web")&&!source.startsWith("https://"))throw new IOException("Fuente de documento inválida");
  String name=UUID.randomUUID().toString();File part=new File(root,name+".part"),target=new File(root,name+".txt");final MessageDigest sha=MessageDigest.getInstance("SHA-256"),identity=MessageDigest.getInstance("SHA-256");identity.update((origin+"|").getBytes("UTF-8"));final long[] size={0};int chars=0;boolean useful=false;StringBuilder heading=new StringBuilder();boolean complete=false;
  try{try(final FileOutputStream file=new FileOutputStream(part);Reader in=input){OutputStream digest=new FilterOutputStream(file){public void close()throws IOException{flush();}public void write(int b)throws IOException{byte[] a={(byte)b};write(a,0,1);}public void write(byte[] b,int o,int n)throws IOException{if(size[0]+n>DOCUMENT_BYTES)throw new IOException("El documento supera64MiB; no incorporé una parte");out.write(b,o,n);sha.update(b,o,n);identity.update(b,o,n);size[0]+=n;}};Writer writer=new OutputStreamWriter(digest,Charset.forName("UTF-8").newEncoder().onMalformedInput(CodingErrorAction.REPORT).onUnmappableCharacter(CodingErrorAction.REPORT));char[] buffer=new char[8192];int n;long checked=0;while((n=in.read(buffer))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException("Importación cancelada");if(chars+n>DOCUMENT_CHARS)throw new IOException("El documento supera16000000 caracteres; conservé la versión anterior");for(int j=0;j<n;j++){if(!Character.isWhitespace(buffer[j]))useful=true;if(heading.length()<80)heading.append(buffer[j]);}writer.write(buffer,0,n);chars+=n;if(size[0]-checked>1048576){checked=size[0];if(root.getUsableSpace()<16777216L)throw new IOException("Falta espacio disponible para continuar");}}writer.close();file.getFD().sync();}
   if(!useful)throw new IOException("No recibí contenido para guardar");if(!part.renameTo(target))throw new IOException("No pude completar el archivo del documento");Doc d=new Doc();d.id=origin.equals("web")?JavaMethodEditor.hash(origin+"|"+source):hex(identity.digest());d.title=title.trim().isEmpty()?heading.toString().trim():title.trim();d.title=d.title.substring(0,Math.min(160,d.title.length()));d.source=source;d.origin=origin;d.saved=saved;d.file=target.getName();d.sha=hex(sha.digest());d.bytes=size[0];d.chars=chars;d.validate();complete=true;return new Stage(d,target);
  }finally{if(!complete){part.delete();target.delete();}}
 }
 synchronized void capacity(List<Doc> docs,boolean keepExisting)throws Exception{long bytes=index.bytes();int count=index.count();Set<String> ids=new HashSet<>();for(Doc d:docs){d.validate();if(!ids.add(d.id))throw new IOException("Documento repetido en el lote");Doc old=index.get(d.id);if(old!=null&&keepExisting)continue;bytes+=d.bytes-(old==null?0:old.bytes);if(old==null)count++;}if(bytes>TOTAL_BYTES||count>MAX_DOCUMENTS)throw new IOException("La biblioteca admite1024 documentos y512MiB de texto UTF-8; no borré conocimientos para hacer lugar");}
 synchronized void install(List<Stage> stages,boolean keepExisting,boolean mark)throws Exception{install(stages,keepExisting,mark,null);}
 synchronized void install(List<Stage> stages,boolean keepExisting,boolean mark,String last)throws Exception{List<File> previous=new ArrayList<>();boolean committed=false;try{List<Doc> docs=new ArrayList<>();for(Stage s:stages)docs.add(s.doc);capacity(docs,keepExisting);long incoming=0;for(Stage s:stages)if(!keepExisting||index.get(s.doc.id)==null)incoming+=s.doc.bytes;if(root.getUsableSpace()<incoming*3+16777216L)throw new IOException("Falta espacio para los documentos y su índice");index.begin();try{for(Stage s:stages){Doc old=index.get(s.doc.id);if(old!=null&&keepExisting)continue;if(old!=null)previous.add(file(old));index.remove(s.doc.id);index.doc(s.doc);indexDocument(s.doc);index.meta("last",s.doc.id);}if(last!=null&&(last.isEmpty()||index.get(last)!=null))index.meta("last",last);if(mark||!stages.isEmpty())index.meta("initialized","1");index.meta("generation",Long.toString(generation()+1));index.end(true);committed=true;}catch(Exception e){rollback();throw e;}}finally{for(Stage s:stages)discardIfUnused(s);if(committed)for(File old:previous)old.delete();}}
 void rollback(){try{index.end(false);}catch(Exception ignored){}}
 void discardIfUnused(Stage s){try{Doc current=index.get(s.doc.id);if(current==null||!current.file.equals(s.doc.file))s.file.delete();}catch(Exception uncertain){/* Keep evidence until a successful reopen can establish references. */}}
 File file(Doc d)throws IOException{File f=new File(root,d.file);if(!f.getCanonicalPath().startsWith(root.getCanonicalPath()+File.separator)||!f.isFile())throw new IOException("Falta el archivo privado de un documento");return f;}
 interface Pieces{void accept(String text,int ordinal)throws Exception;}
 static void pieces(Reader input,Pieces output)throws Exception{try(Reader in=input){char[] buffer=new char[4096];StringBuilder pending=new StringBuilder();int n,ordinal=0;while((n=in.read(buffer))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException("Lectura cancelada");pending.append(buffer,0,n);while(pending.length()>=CHUNK){int end=pending.lastIndexOf(" ",CHUNK);if(end<CHUNK/2)end=CHUNK;if(end>0&&Character.isHighSurrogate(pending.charAt(end-1)))end--;String text=pending.substring(0,end).trim();pending.delete(0,end);if(!text.isEmpty())output.accept(text,ordinal++);}}String text=pending.toString().trim();if(!text.isEmpty())output.accept(text,ordinal);}}
 static Set<String> terms(String text){String n=Normalizer.normalize(text.toLowerCase(Locale.ROOT),Normalizer.Form.NFD);Set<String> out=new TreeSet<>();StringBuilder word=new StringBuilder();for(int i=0;i<=n.length();i++){char c=i<n.length()?n.charAt(i):' ';if(Character.getType(c)==Character.NON_SPACING_MARK)continue;if(c>='a'&&c<='z'||c>='0'&&c<='9'){word.append(c);}else if(word.length()>0){String w=word.toString();if(w.length()>1&&!ReadingKnowledge.STOP.contains(w)){if(w.length()>5&&w.endsWith("s"))w=w.substring(0,w.length()-1);out.add(w);}word.setLength(0);}}return out;}
 static String tokens(String text){StringBuilder s=new StringBuilder();for(String t:terms(text))s.append(t).append(' ');return s.toString();}
 void indexDocument(final Doc d)throws Exception{pieces(reader(new FileInputStream(file(d))),new Pieces(){public void accept(String text,int ordinal)throws Exception{String lower=text.toLowerCase(Locale.ROOT);boolean hint=lower.contains(" es ")||lower.contains(" son ")||lower.contains(" significa ")||lower.contains(": ");index.chunk(d.id,ordinal,text,tokens(text),hint);}});}
 synchronized String put(String title,Reader text,String source,String origin)throws Exception{Stage s=stage(title,text,source,origin,System.currentTimeMillis());install(Collections.singletonList(s),false,true);return "Guardé el documento completo: "+s.doc.title+".\nContenido retenido: "+s.doc.chars+" caracteres · "+s.doc.bytes+" bytes UTF-8.\nFuente: "+(origin.equals("user")?"aporte del usuario":source)+"\nSe consulta por fragmentos desde disco. No recorté el texto ni cambié los pesos del Transformer.";}
 synchronized JSONArray selected(String query)throws Exception{return rows(index.search(ReadingKnowledge.words(query),96),12,8);}
 static JSONArray rows(List<Hit> hits,int maxDocs,int perDoc)throws Exception{Map<String,JSONObject> out=new LinkedHashMap<>();Map<String,Integer> counts=new HashMap<>();for(Hit h:hits){JSONObject row=out.get(h.doc.id);if(row==null){if(out.size()>=maxDocs)continue;row=h.doc.row("");out.put(h.doc.id,row);counts.put(h.doc.id,0);}if(counts.get(h.doc.id)>=perDoc)continue;row.put("text",row.getString("text")+h.text+"\n");counts.put(h.doc.id,counts.get(h.doc.id)+1);}JSONArray rows=new JSONArray();for(JSONObject row:out.values())rows.put(row);return rows;}
 synchronized String summary()throws Exception{StringBuilder s=new StringBuilder("Biblioteca en disco: "+index.count()+" documentos, "+index.bytes()+" bytes UTF-8 y "+index.chunks()+" fragmentos.\n");for(Doc d:index.list(12))s.append("• ").append(d.title).append(" · ").append(d.chars).append(" caracteres\n");return s.append("Los textos completos están en archivos privados y se buscan mediante un índice local; no son pesos neuronales.").toString();}
 synchronized String vocabulary()throws Exception{return summary()+"\nMuestra de vocabulario de hasta32 fragmentos con indicios de definición:\n"+ReadingKnowledge.vocabulary(rows(index.sample(32),16,2));}
 synchronized JSONArray latest()throws Exception{String last=index.meta("last");Doc d=index.get(last);if(d==null)return new JSONArray();return rows(index.first(last,3),1,3);}
 synchronized void clear()throws Exception{List<Doc> old=index.list(MAX_DOCUMENTS);index.begin();try{index.clear();index.meta("initialized","1");index.meta("last","");index.meta("generation",Long.toString(generation()+1));index.end(true);}catch(Exception e){rollback();throw e;}for(Doc d:old)new File(root,d.file).delete();}
 synchronized boolean initialized()throws Exception{return "1".equals(index.meta("initialized"));}synchronized long generation()throws Exception{String g=index.meta("generation");return g.isEmpty()?0:Long.parseLong(g);}
 synchronized JSONArray legacyRows()throws Exception{List<Doc> docs=index.list(MAX_DOCUMENTS);long chars=0;for(Doc d:docs){chars+=d.chars;if(d.chars>KnowledgeNotebook.TEXT||chars>KnowledgeNotebook.BUDGET||docs.size()>KnowledgeNotebook.MAX)throw new IOException("La biblioteca supera el respaldo JSON clásico. Pedime ‘respaldá mi conocimiento’ para guardarla completa por documentos.");}JSONArray rows=new JSONArray();for(Doc d:docs){StringBuilder text=new StringBuilder(d.chars);try(Reader in=reader(new FileInputStream(file(d)))){char[] b=new char[8192];int n;while((n=in.read(b))!=-1)text.append(b,0,n);}rows.put(d.row(text.toString()));}KnowledgeNotebook.validate(rows);return rows;}
 synchronized void restoreLegacy(JSONArray rows)throws Exception{KnowledgeNotebook.validate(rows);if(initialized())return;List<Stage> stages=new ArrayList<>();try{for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);Stage s=stage(r.getString("title"),new StringReader(r.getString("text")),r.getString("source"),r.getString("origin"),r.getLong("saved"));s.doc.id=r.getString("id");s.doc.truncated=r.getBoolean("truncated");stages.add(s);}install(stages,true,true,rows.length()==0?"":rows.getJSONObject(0).getString("id"));}finally{for(Stage s:stages)discardIfUnused(s);}}
}
